 fs.writeFileSync(runner,program,{mode:0o600});fs.writeFileSync(binding,JSON.stringify(data),{mode:0o600});
 const shell='set -euo pipefail\nruntime=$1\nstat(){ case "$2" in %u) printf 996;; %a) printf 600;; *) command stat "$@";; esac; }\n'+guard+'\n[[ -f "$runtime/deployment-receipt.json" ]]\nif [[ "$2" == fail ]];then exit 7;fi\nnode "$3" "$runtime/deployment-receipt.json" "$4" "$5"\n';
